import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

async function getDashboardData(): Promise<DashboardData> {
  const res = await fetch('https://api.example.com/dashboard')

  if (!res.ok) {
    throw new Error('Failed to load dashboard data')
  }

  return res.json()
}

export async function DashboardContent() {
  const data = await getDashboardData()

  return (
    <>
      <CardStats
        totalRevenue={data.totalRevenue}
        totalInvoices={data.totalInvoices}
      />
      <RevenueChart revenue={data.revenue} />
      <LatestInvoices invoices={data.invoices} />
    </>
  )
}
const placeholderRows = ['one', 'two', 'three']

export function DashboardSkeleton() {
  return (
    <div className="dashboard-skeleton" aria-busy="true">
      <p role="status">Loading dashboard data...</p>

      <div className="grid grid-cols-2 gap-4">
        <div className="card" aria-hidden="true">
          <h2>Total Revenue</h2>
          <div className="skeleton-value" />
        </div>
        <div className="card" aria-hidden="true">
          <h2>Total Invoices</h2>
          <div className="skeleton-value" />
        </div>
      </div>

      <div className="chart" aria-hidden="true">
        <h2>Revenue</h2>
        <div className="skeleton-chart" />
      </div>

      <div className="invoices" aria-hidden="true">
        <h2>Latest Invoices</h2>
        <ul>
          {placeholderRows.map((row) => (
            <li key={row}>
              <div className="skeleton-invoice" />
            </li>
          ))}
        </ul>
      </div>
    </div>
  )
}
import { DashboardSkeleton } from './DashboardSkeleton'

export default function Loading() {
  return (
    <main>
      <h1>Dashboard</h1>
      <DashboardSkeleton />
    </main>
  )
}
